import { describe, expect, test } from "vitest"
import { Schema } from "effect"
import { Llm } from "../src/index.js"

describe("Llm", () => {
  test("constructs serializable output values", () => {
    expect(Llm.text("hello", { delay: 0, chunkSize: 3 })).toEqual({
      type: "text",
      text: "hello",
      options: { delay: 0, chunkSize: 3 },
    })
    expect(Llm.reasoning("thinking")).toEqual({
      type: "reasoning",
      text: "thinking",
    })
    expect(Llm.pause(20)).toEqual({ type: "pause", milliseconds: 20 })
    expect(
      Llm.toolCall({
        index: 0,
        id: "call_1",
        name: "read",
        input: { path: "src/example.ts" },
      }),
    ).toEqual({
      type: "toolCall",
      index: 0,
      id: "call_1",
      name: "read",
      input: { path: "src/example.ts" },
    })
    expect(
      Llm.toolCall(
        {
          index: 1,
          id: "call_2",
          name: "patch",
          input: { patchText: "*** Begin Patch\n*** End Patch" },
        },
        { delay: 20, chunkSize: 10 },
      ),
    ).toEqual({
      type: "toolCall",
      index: 1,
      id: "call_2",
      name: "patch",
      input: { patchText: "*** Begin Patch\n*** End Patch" },
      options: { delay: 20, chunkSize: 10 },
    })
    expect(Llm.raw({ usage: { inputTokens: 10 } })).toEqual({
      type: "raw",
      chunk: { usage: { inputTokens: 10 } },
    })
    expect(Llm.finish("tool-calls")).toEqual({
      type: "finish",
      reason: "tool-calls",
    })
    expect(Llm.disconnect()).toEqual({ type: "disconnect" })
  })

  test("decodes raw schema-compatible outputs", () => {
    const decode = Schema.decodeUnknownSync(Llm.Output)

    expect(decode({ type: "text", text: "raw" })).toEqual({
      type: "text",
      text: "raw",
    })
    expect(
      decode({
        type: "toolCall",
        index: 0,
        id: "call_2",
        name: "write",
        input: { path: "notes.txt", contents: "hello" },
      }),
    ).toEqual({
      type: "toolCall",
      index: 0,
      id: "call_2",
      name: "write",
      input: { path: "notes.txt", contents: "hello" },
    })
  })

  test("rejects invalid output values", () => {
    const decode = Schema.decodeUnknownSync(Llm.Output)

    expect(() => Llm.pause(-1)).toThrow()
    expect(() => Llm.pause(Number.POSITIVE_INFINITY)).toThrow()
    expect(() => Llm.text("hello", { delay: -1 })).toThrow()
    expect(() => Llm.text("hello", { chunkSize: 0 })).toThrow()
    expect(() => Llm.text("hello", { chunkSize: 1.5 })).toThrow()
    expect(() => Llm.toolCall({ index: -1, id: "call_3", name: "read", input: {} })).toThrow()
    expect(() => Llm.toolCall({ index: 1.5, id: "call_3", name: "read", input: {} })).toThrow()
    expect(() =>
      Llm.toolCall(
        { index: 0, id: "call_3", name: "read", input: {} },
        { chunkSize: 0 },
      ),
    ).toThrow()
    expect(() =>
      Llm.toolCall({
        index: Number.NaN,
        id: "call_3",
        name: "read",
        input: {},
      }),
    ).toThrow()
    expect(() =>
      Llm.toolCall({
        index: Number.POSITIVE_INFINITY,
        id: "call_3",
        name: "read",
        input: {},
      }),
    ).toThrow()
    expect(() => decode({ type: "finish", reason: "unknown" })).toThrow()
    expect(() =>
      decode({
        type: "toolCall",
        index: "0",
        id: "call_3",
        name: "read",
        input: {},
      }),
    ).toThrow()
  })
})

import { defineScript, Llm, type JsonValue, type Ui } from "../../src/index.js"
import * as Effect from "effect/Effect"
import * as Stream from "effect/Stream"

export default defineScript({
  setup: ({ fs }) => fs.writeFile(
    "src/ledger.ts",
    [
      "export const credits = [8, 13, 21]",
      "export const total = credits.reduce((sum, value) => sum + value, 0)",
      "",
    ].join("\n"),
  ),

  run: ({ llm, ui }) =>
    Effect.gen(function* () {
      let phase = 0

      yield* llm.serve((request) => {
        if (isTitleRequest(request.body)) {
          return Stream.make(Llm.text("Delegating ledger checks"))
        }

        if (phase === 0 || phase === 3) {
          const tool = subagentTool(request.body)
          const first = phase === 0
          phase++
          return Stream.make(
            Llm.reasoning(
              first
                ? "I will delegate repository inspection to an explore agent."
                : "I will ask a general agent to independently verify the result.",
            ),
            Llm.toolCall({
              index: 0,
              id: first ? "call_explore_ledger" : "call_verify_ledger",
              name: tool,
              input: subagentInput(
                tool,
                first ? "Explore the ledger" : "Verify the total",
                first
                  ? "Read src/ledger.ts and report its exports and values."
                  : "Independently calculate the total exported by src/ledger.ts.",
                first ? "explore" : "general",
              ),
            }),
            Llm.finish("tool-calls"),
          )
        }

        if (phase === 1) {
          phase++
          return Stream.make(
            Llm.text(
              "The ledger exports credits containing 8, 13, and 21, plus a computed total.",
            ),
          )
        }
        if (phase === 2) {
          phase++
          return Stream.make(
            Llm.text(
              "First delegation complete: the explore agent inspected the ledger.",
            ),
          )
        }
        if (phase === 4) {
          phase++
          return Stream.make(
            Llm.text("The independent calculation is 8 + 13 + 21 = 42."),
          )
        }

        phase++
        return Stream.make(
          Llm.text(
            "Second delegation complete: the general agent confirmed total 42.",
          ),
        )
      })

      yield* ui.submit("Use an explore subagent to inspect src/ledger.ts.")
      yield* ui.waitFor("First delegation complete", { timeout: 30_000 })
      yield* Effect.sleep(250)
      yield* ui.screenshot("subagents-first-complete")

      yield* openSubagents(ui)
      yield* ui.waitFor("Subagents")
      yield* ui.enter()
      yield* ui.screenshot("subagents-child")
      yield* ui.press("escape")
      yield* ui.waitFor("First delegation complete")

      yield* ui.submit("Now use a general subagent to verify the total independently.")
      yield* ui.waitFor("Second delegation complete", { timeout: 30_000 })
      yield* Effect.sleep(250)
      yield* ui.screenshot("subagents-second-complete")
    }),
})

const openSubagents = Effect.fn("openSubagents")(function* (ui: Ui) {
  yield* ui.press("x", { ctrl: true })
  yield* ui.arrow("down")
})

function subagentTool(body: JsonValue) {
  const names = offeredTools(body)
  if (names.includes("subagent")) return "subagent"
  if (names.includes("task")) return "task"
  throw new Error(`OpenCode did not offer a subagent tool: ${names.join(", ")}`)
}

function subagentInput(
  tool: string,
  description: string,
  prompt: string,
  agent: string,
): JsonValue {
  if (tool === "subagent") return { agent, description, prompt }
  return { subagent_type: agent, description, prompt }
}

function offeredTools(body: JsonValue) {
  if (!isJsonObject(body)) return []
  const tools = body.tools
  if (!Array.isArray(tools)) return []
  return tools.flatMap((tool) => {
    if (!isJsonObject(tool)) return []
    const definition = tool.function
    if (!isJsonObject(definition) || typeof definition.name !== "string") return []
    return [definition.name]
  })
}

function isJsonObject(
  value: JsonValue | undefined,
): value is { readonly [key: string]: JsonValue } {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function isTitleRequest(body: unknown) {
  return JSON.stringify(body).includes("title generator")
}

import { describe, expect, it } from "vitest"
import * as Deferred from "effect/Deferred"
import * as Effect from "effect/Effect"
import * as Stream from "effect/Stream"
import { LlmControllerError } from "../../src/driver/llm-errors.js"
import * as LlmState from "../../src/driver/llm-state.js"

const completion = () =>
  Effect.runSync(Deferred.make<void, LlmControllerError>())

const request = (id: string): LlmState.AttachedRequest =>
  ({
    request: { id, url: "https://example.test", body: {} },
    backend: {} as LlmState.AttachedRequest["backend"],
  })

const handler: LlmState.ServeHandler = () => Stream.empty

describe("LlmState", () => {
  it("allows configuring a title handler after a default title, but only once", () => {
    const [state, first] = LlmState.startTitle(LlmState.initial, completion())
    expect(Effect.runSync(first.handler(request("title").request, first.index))).toBe("OpenCode Drive")
    expect(LlmState.rejectTitle(state)).toBeUndefined()
    const configured = LlmState.configureTitle(state, () => Effect.succeed("Configured title"))
    expect(LlmState.rejectTitle(configured)).toMatchObject({ _tag: "LlmModeError", operation: "title" })
    const [, next] = LlmState.startTitle(configured, completion())
    expect(next.index).toBe(1)
    expect(Effect.runSync(next.handler(request("title").request, next.index))).toBe("Configured title")
  })
  it("rejects queue/send after serve mode is selected", () => {
    const state = LlmState.serve(LlmState.initial, handler)
    expect(LlmState.rejectEnqueue(state, "queue")).toMatchObject({
      _tag: "LlmModeError",
      operation: "queue",
    })
  })

  it("rejects serve after queue mode is selected", () => {
    const state = LlmState.enqueue(LlmState.initial, { output: [] })
    expect(LlmState.rejectServe(state)).toMatchObject({
      _tag: "LlmModeError",
      operation: "serve",
    })
  })

  it("rejects control calls while settling", () => {
    const state = LlmState.beginSettling(LlmState.initial)
    expect(LlmState.rejectEnqueue(state, "send")).toMatchObject({
      _tag: "LlmControllerError",
      operation: "send",
    })
  })

  it("selects no job until a queued request has a queued response", () => {
    const requested = LlmState.pushRequest(LlmState.initial, request("r1"))
    expect(LlmState.nextNormal(requested)).toBeUndefined()

    const responded = LlmState.enqueue(requested, { output: [] })
    const start = LlmState.nextNormal(responded)
    expect(start?.request.request.id).toBe("r1")
    expect(start?.source._tag).toBe("Queued")
  })

  it("serve mode runs requests without queued responses", () => {
    const state = LlmState.pushRequest(
      LlmState.serve(LlmState.initial, handler),
      request("r1"),
    )
    expect(LlmState.nextNormal(state)?.source._tag).toBe("Served")
  })

  it("startNormal consumes the request and response and bumps the index", () => {
    const state = LlmState.enqueue(
      LlmState.pushRequest(LlmState.initial, request("r1")),
      { output: [] },
    )
    const start = LlmState.nextNormal(state)!
    const next = LlmState.startNormal(state, start, completion())
    expect(next.requests).toHaveLength(0)
    expect(next.responses).toHaveLength(0)
    expect(next.activeNormal).toHaveLength(1)
    expect(next.requestIndex).toBe(1)
    expect(LlmState.nextNormal(next)).toBeUndefined()
  })

  it("settles Done when idle, Wait while work remains, Fail on unexpected requests", () => {
    expect(LlmState.inspectSettlement(LlmState.initial)._tag).toBe("Done")

    const waiting = LlmState.enqueue(LlmState.initial, { output: [] })
    expect(LlmState.inspectSettlement(waiting)._tag).toBe("Wait")

    const unexpected = LlmState.pushRequest(
      LlmState.enqueue(LlmState.initial, { output: [] }),
      request("r1"),
    )
    const drained = LlmState.startNormal(
      unexpected,
      LlmState.nextNormal(unexpected)!,
      completion(),
    )
    const late = LlmState.pushRequest(drained, request("r2"))
    const settlement = LlmState.inspectSettlement({
      ...late,
      activeNormal: [],
    })
    expect(settlement).toMatchObject({
      _tag: "Fail",
      error: { _tag: "LlmSettlementError", unexpectedRequests: 1 },
    })
  })

  it("records only the first failure and keeps it", () => {
    const error = (message: string) =>
      new LlmControllerError({ operation: "test", message })
    const first = LlmState.recordFailure(LlmState.initial, error("first"))
    expect(first[1].isFirst).toBe(true)
    const second = LlmState.recordFailure(first[0], error("second"))
    expect(second[1].isFirst).toBe(false)
    expect(second[1].failure).toBe(first[1].failure)
  })
})

import { describe, expect, it, vi } from "@effect/vitest"
import { Effect, Fiber } from "effect"
import { TestClock } from "effect/testing"
import * as LlmController from "../../src/driver/llm-controller.js"
import * as Llm from "../../src/llm/index.js"
import * as SimulationConnector from "../../src/simulation/connector.js"
import { sendError, sendResult, startTransportPeer } from "../simulation/transport-peer.js"

const request = {
  id: "exchange-1",
  url: "https://api.openai.com/v1/responses",
  body: { model: "test-model" },
}

describe("LlmController", () => {
  it.live("preserves response state across backend generations", () => {
    const peer = (id: string) =>
      startTransportPeer(({ request: frame, socket }) => {
        if (frame.method === "llm.attach")
          socket.send(
            JSON.stringify({
              jsonrpc: "2.0",
              method: "llm.request",
              params: { ...request, id },
            }),
          )
        sendResult(
          socket,
          frame,
          frame.method === "llm.attach" ? { attached: true } : { ok: true },
        )
      })
    const first = peer("generation-1")
    const second = peer("generation-2")

    return Effect.gen(function* () {
      yield* Effect.addFinalizer(() =>
        Effect.promise(() => Promise.all([first.stop(), second.stop()])),
      )
      const llm = yield* LlmController.make()
      const firstBackend = yield* SimulationConnector.backend(first.url)
      const firstAttachment = yield* llm.attach(firstBackend)
      yield* llm.send(Llm.text("first", { delay: 0 }))
      yield* firstAttachment.detach()

      const secondBackend = yield* SimulationConnector.backend(second.url)
      yield* llm.attach(secondBackend)
      yield* llm.send(Llm.text("second", { delay: 0 }))
      yield* llm.settle()

      expect(
        first.received.some(({ request: frame }) =>
          JSON.stringify(frame).includes("first"),
        ),
      ).toBe(true)
      expect(
        second.received.some(({ request: frame }) =>
          JSON.stringify(frame).includes("second"),
        ),
      ).toBe(true)
    })
  })

  it.live("queues and streams one future response", () => {
    const peer = startTransportPeer(({ request: frame, socket }) => {
      if (frame.method === "llm.attach")
        socket.send(
          JSON.stringify({
            jsonrpc: "2.0",
            method: "llm.request",
            params: request,
          }),
        )
      sendResult(socket, frame, frame.method === "llm.attach" ? { attached: true } : { ok: true })
    })

    return Effect.gen(function* () {
      yield* Effect.addFinalizer(() => Effect.promise(() => peer.stop()))
      const backend = yield* SimulationConnector.backend(peer.url)
      const llm = yield* LlmController.make(backend)
